{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "陈宇",
      "role": "protagonist",
      "identity": "火星基地宇航员/植物学家",
      "traits": ["坚韧", "温柔", "执着", "孤独"],
      "overt_motivation": "在火星完成种植任务，维持基地运转等待救援",
      "covert_motivation": "内心深处渴望与妻子重逢，即使只有万分之一的可能",
      "secret_fear": "再次失去她，确认她只是自己的幻觉",
      "misperception_of_other": "以为她只是自己因孤独产生的幻觉或投影",
      "hidden_connection": "两人曾共同研究过量子纠缠通讯理论，她的'归来'与这项研究有关"
    },
    {
      "name": "林曦",
      "role": "deuteragonist",
      "identity": "已故地球科学家/以量子态存在",
      "traits": ["聪慧", "乐观", "深情", "神秘"],
      "overt_motivation": "帮助丈夫在火星生存下去，不让他孤独",
      "covert_motivation": "找到自己以量子态存在的意义，确认这份'爱'能跨越生死",
      "secret_fear": "自己只是他脑海中的幻影，终有一天会彻底消失",
      "misperception_of_other": "以为陈宇会因她的'非人'存在而恐惧或排斥",
      "hidden_connection": "地球毁灭前她的意识被量子化，通过他们共同研究的理论找到陈宇"
    }
  ],
  "supporting_characters": [
    {
      "name": "指挥中心",
      "function": "助力",
      "identity": "地球救援指挥中心（声音/通讯）",
      "description": "定期与陈宇通讯，提供任务指导和心理支持，后期发现氧气异常但选择保密"
    }
  ],
  "relationship_dynamics": "陈宇与林曦是生死相隔的夫妻，因量子纠缠奇迹重逢。初期陈宇以为她是幻觉，林曦以为会被排斥；中期两人在火星日常中重建亲密，互相确认存在；后期共同面对'她能否永久存在'的疑问，最终找到属于两人的生存方式——在荒芜宇宙中，爱让不可能成为可能。"
}"}

{"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立火星基地世界观，引入陈宇的孤独日常，收到神秘信号发现妻子'归来'的奇迹",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "红色星球的清晨",
        "core_event": "陈宇在火星基地开始新一天的种植工作，收到三年前地球毁灭前的延迟信号",
        "emotional_tone": "孤独中带着希望",
        "key_scenes": ["火星日出景象", "温室里照料土豆苗", "信号接收警报响起", "听到妻子熟悉的声音"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "摩斯密码的秘密",
        "core_event": "陈宇反复聆听信号，发现隐藏的摩斯密码'我在你身后'，但回头空无一人",
        "emotional_tone": "疑惑与悸动",
        "key_scenes": ["信号分析", "摩斯密码破译", "转身寻找", "氧气数据异常发现"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "多出来的氧气消耗",
        "core_event": "陈宇确认基地氧气消耗数据显示有第二人存在，第一次'感知'到她的触碰",
        "emotional_tone": "震惊与温柔",
        "key_scenes": ["检查生命维持系统", "数据反复确认", "手臂被轻触的感觉", "轻声呼唤她的名字"]
      }
    ],
    "turning_point": "陈宇确认林曦真的以某种形式'回来'了，不是幻觉，她能在特定条件下与他互动"
  },
  "act_two": {
    "description": "两人在火星重建日常生活，林曦帮助陈宇种植，揭示她如何回来的真相，面临存在危机",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "两个人的温室",
        "core_event": "林曦开始帮助陈宇照料植物，两人恢复婚前的相处模式，温馨日常",
        "emotional_tone": "温馨甜蜜",
        "key_scenes": ["她指导他修剪枝叶", "一起给土豆浇水", "久违的对话与笑声", "她无法触碰实物但能影响电子设备"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "量子纠缠的奇迹",
        "core_event": "林曦解释自己如何回来——地球毁灭前她的意识被量子化，通过他们共同研究的理论找到陈宇",
        "emotional_tone": "感动与震撼",
        "key_scenes": ["深夜长谈", "回忆共同研究时光", "量子态存在原理解释", "陈宇流泪拥抱空气"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "指挥中心的疑问",
        "core_event": "地球指挥中心发现氧气消耗异常，询问陈宇，他选择隐瞒林曦的存在",
        "emotional_tone": "紧张与保护",
        "key_scenes": ["例行通讯", "指挥官询问数据异常", "陈宇撒谎说是设备故障", "林曦在旁微笑"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "存在的边界",
        "core_event": "林曦发现自己存在不稳定，可能随时消失，陈宇疯狂寻找留住她的方法",
        "emotional_tone": "焦虑与深情",
        "key_scenes": ["林曦身影闪烁", "陈宇查阅所有研究资料", "她安慰他不要害怕", "两人约定无论怎样都在一起"]
      }
    ],
    "turning_point": "陈宇发现可以通过基地的量子通讯设备增强林曦的存在稳定性，但需要冒着与地球失联的风险"
  },
  "act_three": {
    "description": "陈宇做出选择，切断与地球的联系以留住林曦，两人在火星建立真正的家园，迎来HE结局",
    "key_chapters": [
      {
        "chapter_number": 8,
        "chapter_title": "选择",
        "core_event": "陈宇面临抉择——保持与地球联系等待救援但林曦会消失，或切断联系留住她",
        "emotional_tone": "挣扎与坚定",
        "key_scenes": ["设备改造准备", "林曦劝他选择救援", "陈宇的内心独白", "最终决定"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "红色家园",
        "core_event": "陈宇改造设备成功，林曦的存在稳定下来，两人开始真正的火星生活",
        "emotional_tone": "希望与幸福",
        "key_scenes": ["设备启动", "林曦实体化程度增强", "第一次真正拥抱", "土豆丰收"]
      },
      {
        "chapter_number": 10,
        "chapter_title": "宇宙中只有我们",
        "core_event": "HE结局——两人在火星建立家园，陈宇记录他们的故事，爱跨越生死与时空",
        "emotional_tone": "圆满与温暖",
        "key_scenes": ["火星日落", "两人依偎看地球方向", "陈宇的日志记录", "未来生活的憧憬"]
      }
    ]
  }
}"}

environment.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "characters.schema.json",
  "title": "小说人物设计",
  "description": "人物一致性的参考依据，避免角色崩坏",
  "type": "object",
  "required": ["main_characters"],
  "properties": {
    "main_characters": {
      "type": "array",
      "description": "主角/核心角色数组",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": [
          "name",
          "role",
          "traits",
          "overt_motivation",
          "covert_motivation",
          "secret_fear"
        ],
        "properties": {
          "name": {
            "type": "string",
            "description": "角色姓名"
          },
          "role": {
            "type": "string",
            "enum": ["protagonist", "deuteragonist"],
            "description": "角色类型：protagonist=第一主角，deuteragonist=第二主角"
          },
          "identity": {
            "type": "string",
            "description": "身份职业/社会角色"
          },
          "traits": {
            "type": "array",
            "description": "核心性格特质关键词（3-5个）",
            "items": {
              "type": "string"
            },
            "minItems": 3,
            "maxItems": 5
          },
          "overt_motivation": {
            "type": "string",
            "description": "显性动机（表面目标）"
          },
          "covert_motivation": {
            "type": "string",
            "description": "隐性动机（深层需求）"
          },
          "secret_fear": {
            "type": "string",
            "description": "秘密恐惧（内心脆弱点）"
          },
          "misperception_of_other": {
            "type": "string",
            "description": "对其他主角的错位认知"
          },
          "hidden_connection": {
            "type": "string",
            "description": "与其他角色的隐藏连接"
          }
        }
      }
    },
    "supporting_characters": {
      "type": "array",
      "description": "配角/次要角色数组",
      "items": {
        "type": "object",
        "required": ["name", "function"],
        "properties": {
          "name": {
            "type": "string",
            "description": "配角姓名"
          },
          "function": {
            "type": "string",
            "enum": ["助力", "阻碍", "反转点"],
            "description": "对主角的作用类型"
          },
          "identity": {
            "type": "string",
            "description": "配角身份"
          },
          "description": {
            "type": "string",
            "description": "配角简要描述"
          }
        }
      }
    },
    "relationship_dynamics": {
      "type": "string",
      "description": "角色关系动态描述"
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "creative_intent.schema.json",
  "title": "小说创作意图配方",
  "description": "记录用户需求理解和配方选择结果，作为创作的北极星",
  "type": "object",
  "required": ["user_need", "inspiration_state", "extracted_elements", "selected_recipe", "one_sentence_synopsis"],
  "properties": {
    "user_need": {
      "type": "string",
      "description": "用户的原始输入文本",
      "minLength": 1
    },
    "inspiration_state": {
      "type": "string",
      "enum": ["no_inspiration", "vague_inspiration", "clear_inspiration"],
      "description": "用户创作时的灵感清晰程度"
    },
    "extracted_elements": {
      "type": "object",
      "description": "从用户输入中提取的创作关键要素",
      "required": ["emotion_verbs", "scene_elements", "relationship_tension"],
      "properties": {
        "emotion_verbs": {
          "type": "array",
          "description": "情感动词/核心动作（决定X轴剧情模式）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "scene_elements": {
          "type": "array",
          "description": "场景要素/世界观元素（决定Y轴标签）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "relationship_tension": {
          "type": "array",
          "description": "人物关系张力/冲突来源",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "user_preferences": {
          "type": "object",
          "description": "用户的情感偏好和禁忌",
          "properties": {
            "desired_emotion": {
              "type": "string",
              "description": "期望的情感倾向"
            },
            "forbidden": {
              "type": "array",
              "description": "明确拒绝的元素",
              "items": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "selected_recipe": {
      "type": "object",
      "description": "用户选定的创作配方（X-Y轴化学反应组合）",
      "required": [
        "x_axis_mode_id",
        "x_axis_mode_name",
        "y_axis_tags",
        "reaction_strength",
        "tension_stars",
        "forbidden_elements"
      ],
      "properties": {
        "x_axis_mode_id": {
          "type": "string",
          "pattern": "^[A-G]\\d{1,2}$",
          "enum": [
            "A1", "A2", "A3", "A4", "A5", "A6",
            "B7", "B8", "B9", "B10", "B11", "B12",
            "C13", "C14", "C15", "C16", "C17", "C18",
            "D19", "D20", "D21", "D22", "D23",
            "E24", "E25", "E26", "E27", "E28",
            "F29", "F30", "F31", "F32", "F33", "F34",
            "G35", "G36"
          ],
          "description": "普罗蒂36种剧情模式的标识符"
        },
        "x_axis_mode_name": {
          "type": "string",
          "description": "X轴模式的中文名称"
        },
        "y_axis_tags": {
          "type": "array",
          "description": "现代网文核心标签（表达载体）",
          "items": {
            "type": "string",
            "enum": [
              "双向暗恋",
              "系统流",
              "无限流",
              "种田流",
              "赛博朋克",
              "规则怪谈",
              "重生/穿越",
              "商战权谋",
              "克苏鲁",
              "第四天灾",
              "仙侠修真",
              "刑侦悬疑"
            ]
          },
          "minItems": 2,
          "maxItems": 3
        },
        "reaction_strength": {
          "type": "string",
          "enum": ["↗", "↘", "✷"],
          "description": "X轴与Y轴的化学反应强度符号"
        },
        "tension_stars": {
          "type": "integer",
          "minimum": 1,
          "maximum": 5,
          "description": "故事张力指数（1-5星）"
        },
        "forbidden_elements": {
          "type": "array",
          "description": "避雷红线（创作禁忌元素）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "x_axis_display": {
          "type": "string",
          "description": "X轴模式在故事中的具体显影方式"
        },
        "y_axis_combination_effect": {
          "type": "string",
          "description": "Y轴标签组合产生的效应描述"
        },
        "reaction_formula": {
          "type": "string",
          "description": "化学反应公式的一句话描述"
        },
        "platform_fit": {
          "type": "array",
          "description": "适合发布的平台类型",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "one_sentence_synopsis": {
      "type": "string",
      "description": "一句话故事梗概（30-50字）",
      "minLength": 30,
      "maxLength": 50
    }
  }
}

